# Now build the schedule using these 7 disjoint subspaces
# Each subspace S = {0, a, b, a^b} gives a parallel class
# The cosets are v + S for v in GF(2)^5

subspaces = [
    {1, 16, 17},    # basis (00001, 10000)
    {2, 29, 31},    # basis (00010, 11101)
    {3, 20, 23},    # basis (00011, 10100)
    {4, 18, 22},    # basis (00100, 10010)
    {5, 11, 14},    # basis (00101, 01011)
    {6, 24, 30},    # basis (00110, 11000)
    {7, 27, 28},    # basis (00111, 11011)
]

n_golfers = 32
n_weeks = 7
n_groups = 8

schedule = [[-1 for _ in range(n_golfers)] for _ in range(n_weeks)]

for w, subspace in enumerate(subspaces):
    # For each subspace, we need to find the 8 cosets
    # The subspace is {0, a, b, a^b} where a and b are the basis vectors
    # Extract a and b from the subspace
    elements = list(subspace)
    # The subspace contains 0, a, b, a^b
    # We know 0 is not in the subspace (we stored only non-zero elements)
    # Actually wait - the subspace is {0, a, b, a^b} but we stored only {a, b, a^b}
    # So the full subspace is {0} ∪ subspace

    full_subspace = {0} | subspace

    # Find cosets
    assigned = [False] * 32
    group_of = {}

    for v in range(32):
        if not assigned[v]:
            coset = {v ^ x for x in full_subspace}
            g = len(group_of)
            for elem in coset:
                group_of[elem] = g
                assigned[elem] = True

    for p in range(32):
        schedule[w][p] = group_of[p]

# Verify
pair_weeks = {}
valid = True
for w in range(n_weeks):
    groups = [[] for _ in range(n_groups)]
    for p in range(n_golfers):
        groups[schedule[w][p]].append(p)
    for g in range(n_groups):
        if len(groups[g]) != 4:
            print(f"Week {w}, group {g} has {len(groups[g])} members: {groups[g]}")
            valid = False
        for i in range(len(groups[g])):
            for j in range(i+1, len(groups[g])):
                pair = (groups[g][i], groups[g][j])
                if pair in pair_weeks:
                    print(f"Pair {pair} appears in weeks {pair_weeks[pair]} and {w}")
                    valid = False
                pair_weeks[pair] = w

if valid:
    print("Schedule is valid!")
    flat = []
    for w in range(n_weeks):
        for p in range(n_golfers):
            flat.append(schedule[w][p])
    print("Flat list:", flat)
    print("Length:", len(flat))

    # Also print the groups for verification
    for w in range(n_weeks):
        groups = [[] for _ in range(n_groups)]
        for p in range(n_golfers):
            groups[schedule[w][p]].append(p)
        print(f"Week {w}: {groups}")
else:
    print("Schedule is invalid")
